def containsNearbyDuplicate(self, nums: list[int], k: int) -> bool:
    window: set[int] = set()
    for i, x in enumerate(nums):
        if i > k:
            window.discard(nums[i - k - 1])
        if x in window:
            return True
        window.add(x)
    return False

